<?php
namespace App\Http\Controllers;
use App\Models\{PurchaseBill,Contact,Account,Currency,TaxCode};use App\Services\PurchaseService;use Illuminate\Http\Request;
class PurchaseController {public function index(){return view('purchases.index',['bills'=>PurchaseBill::forCompany(auth()->user()->company_id)->with('contact')->latest('bill_date')->paginate(50)]);}public function create(){return view('purchases.create',$this->formData());}public function store(Request $r){$d=$r->validate(['contact_id'=>'required|integer','bill_date'=>'required|date','due_date'=>'nullable|date','supplier_reference'=>'nullable|string|max:255','currency_id'=>'required|integer','exchange_rate'=>'required|decimal:1,10','lines'=>'required|array|min:1','lines.*.description'=>'required|string|max:1000','lines.*.quantity'=>'required|decimal:0,4','lines.*.unit_price'=>'required|decimal:0,6','lines.*.expense_account_id'=>'required|integer','lines.*.tax_code_id'=>'nullable|integer']);$b=app(PurchaseService::class)->createDraft($r->user()->company_id,$r->user()->id,$d,$d['lines']);return redirect()->route('purchases.show',$b);}public function show(PurchaseBill $bill){return view('purchases.show',['bill'=>$bill->load(['lines','contact','currency'])]);}public function post(PurchaseBill $bill){app(PurchaseService::class)->post($bill,auth()->id());return back()->with('ok','Bill posted.');}public function credit(Request $r,PurchaseBill $bill){$d=$r->validate(['bill_date'=>'required|date','exchange_rate'=>'required|decimal:1,10','lines'=>'required|array|min:1','lines.*.description'=>'required|string|max:1000','lines.*.quantity'=>'required|decimal:0,4','lines.*.unit_price'=>'required|decimal:0,6','lines.*.expense_account_id'=>'required|integer','lines.*.tax_code_id'=>'nullable|integer']);$c=app(PurchaseService::class)->createCredit($bill,$r->user()->id,$d,$d['lines']);return redirect()->route('purchases.show',$c)->with('ok','Credit draft created.');}private function formData():array{$c=auth()->user()->company_id;return ['contacts'=>Contact::forCompany($c)->whereIn('type',['supplier','both'])->where('active',1)->orderBy('name')->get(),'accounts'=>Account::forCompany($c)->where('is_postable',1)->where('active',1)->whereIn('type',['expense','asset'])->orderBy('code')->get(),'currencies'=>Currency::where('active',1)->get(),'taxes'=>TaxCode::forCompany($c)->where('active',1)->whereIn('type',['purchase','both'])->orderBy('code')->get()];}}
